	["Action Bar End Caps"] = "행동 단축바 끝 장식", -- draft
	["Also darken the gryphons / end caps and border art of the main action bar."] = "주 행동 단축바의 그리핀 / 끝 장식과 테두리 그림도 어둡게 합니다.", -- draft
	["Health bar backgrounds/borders and cast bars on nameplates."] = "이름표의 생명력 막대 배경/테두리와 시전바.", -- draft
	["Personal Display"] = "개인 표시기", -- draft
