	["Cooldown Manager"] = "재사용 대기시간 관리자", -- draft
	["Icon frames and bar backgrounds of the Essential, Utility and Buff cooldown viewers."] = "핵심, 보조, 강화 효과 재사용 대기시간 보기의 아이콘 테두리와 막대 배경.", -- draft
	["Micro Menu & Bag Bar"] = "마이크로 메뉴 및 가방 바", -- draft
