	["Short / Max + Percent (8.2k / 10k | 82%)"] = "짧게 / 최대 + 백분율 (8.2k / 10k | 82%)", -- draft
	["Position"] = "위치", -- draft
	["Where the text sits on the bar."] = "막대 위 글자의 위치.", -- draft
	["Center"] = "가운데", -- draft
	["Left"] = "왼쪽", -- draft
	["Right"] = "오른쪽", -- draft
	["Horizontal Offset"] = "가로 오프셋", -- draft
	["Nudge the text left (negative) or right (positive) from where Blizzard places its own bar text."] = "블리자드가 막대 글자를 두는 위치에서 글자를 왼쪽(음수) 또는 오른쪽(양수)으로 옮깁니다.", -- draft
	["Vertical Offset"] = "세로 오프셋", -- draft
	["Nudge the text down (negative) or up (positive)."] = "글자를 아래(음수) 또는 위(양수)로 옮깁니다.", -- draft
	["Font Size"] = "글자 크기", -- draft
	["Text size. Default follows the status bar text font of the game (and the Fonts module)."] = "글자 크기. 기본값은 게임의 상태바 숫자 글꼴(과 글꼴 모듈)을 따릅니다.", -- draft
	["Values Font"] = "값 글꼴", -- draft
	["The face of the health and power values on the player, target and focus frames. Shared: the Interface text's face (Look > Fonts)."] = "플레이어, 대상, 주시 대상 창의 생명력과 자원 값 글꼴. 공유: 인터페이스 글자의 글꼴(외형 > 글꼴).", -- draft
	["Shared"] = "공유", -- draft
	-- CooldownText
	["Cooldown Timers"] = "재사용 대기시간 타이머", -- draft
	["Large countdown numbers on action bar cooldowns and nameplate auras, coloured by time left."] = "행동 단축바 재사용 대기시간과 이름표 효과 위의 큰 카운트다운 숫자, 남은 시간에 따라 색이 바뀝니다.", -- draft
	["Countdowns on every cooldown, coloured by how long you still have to wait."] = "모든 재사용 대기시간 위의 카운트다운, 얼마나 더 기다려야 하는지에 따라 색이 바뀝니다.", -- draft
	["Countdown numbers on action bar cooldowns and nameplate auras, coloured by the time left."] = "행동 단축바 재사용 대기시간과 이름표 효과 위의 카운트다운 숫자, 남은 시간에 따라 색이 바뀝니다.", -- draft
	["Show On"] = "표시 위치", -- draft
	["Action, pet, stance and flyout buttons."] = "행동, 소환수, 태세, 펼침 버튼.", -- draft
	["Nameplate Auras"] = "이름표 효과", -- draft
	["Buff, debuff and crowd control icons on nameplates. While Buffs & Debuffs puts your debuffs on enemy nameplates, those icons are MelloUI's own and show their own time: this switch does not reach them."] = "이름표의 강화, 약화, 군중 제어 아이콘. 강화 및 약화 효과가 내 약화 효과를 적 이름표에 올리는 동안 그 아이콘은 MelloUI의 것이며 자체 시간을 보여 줍니다: 이 스위치는 거기에 닿지 않습니다.", -- draft
	["Timer"] = "타이머", -- draft
	["Minimum Duration"] = "최소 지속 시간", -- draft
	["Cooldowns shorter than this show no text (2 s skips the global cooldown)."] = "이보다 짧은 재사용 대기시간은 글자를 표시하지 않습니다(2초면 전역 재사용 대기시간을 건너뜀).", -- draft
	["Text Size"] = "글자 크기", -- draft
	["Text height relative to the icon size."] = "아이콘 크기에 대한 글자 높이.", -- draft
	["Show Tenths Below 5s"] = "5초 미만 소수점 표시", -- draft
	["Show 4.3 instead of 5 when the cooldown is about to finish."] = "재사용 대기시간이 곧 끝날 때 5 대신 4.3을 표시합니다.", -- draft
	["Colour And Size By Time Left"] = "남은 시간에 따른 색과 크기", -- draft
	["Red and larger under 5 s (1.3 times the Text Size), yellow under a minute, dim white and smaller for minutes (0.8 times), grey and smaller still for hours (0.75 times). Off: every timer is white at the Text Size."] = "5초 미만은 빨갛고 크게(글자 크기의 1.3배), 1분 미만은 노랗게, 분 단위는 흐린 흰색으로 작게(0.8배), 시간 단위는 회색으로 더 작게(0.75배). 끄기: 모든 타이머가 글자 크기의 흰색입니다.", -- draft
	-- Tweaks
	["Tweaks"] = "조정", -- draft
	["Hide the micro menu and bag bar, and scale the floating combat text."] = "마이크로 메뉴와 가방 바를 숨기고 떠오르는 전투 문자의 크기를 조절합니다.", -- draft
	["Small knobs with a big effect. Hide what you never click, scale what you never see."] = "작은 손잡이, 큰 효과. 누르지 않는 것은 숨기고 보이지 않던 것은 키우세요.", -- draft
	["Hide Frames"] = "창 숨기기", -- draft
	["Hide Micro Menu"] = "마이크로 메뉴 숨기기", -- draft
	["Hide the row of menu buttons (character, spellbook, talents, ...). Still shown while Edit Mode is open."] = "메뉴 버튼 줄(캐릭터, 마법책, 특성, ...)을 숨깁니다. 편집 모드가 열려 있는 동안에는 보입니다.", -- draft
	["Hide Bag Bar"] = "가방 바 숨기기", -- draft
	["Hide the backpack and bag slot buttons. Still shown while Edit Mode is open. Bags can still be opened with their keybinds."] = "소지품과 가방 칸 버튼을 숨깁니다. 편집 모드가 열려 있는 동안에는 보입니다. 가방은 단축키로 계속 열 수 있습니다.", -- draft
	["Hide Minimap Coordinates"] = "미니맵 좌표 숨기기", -- draft
	["Hide the player coordinates the client writes under the minimap."] = "클라이언트가 미니맵 아래에 쓰는 플레이어 좌표를 숨깁니다.", -- draft
	["Bag Slots On Bag Window"] = "가방 창의 가방 칸", -- draft
	["While the bag bar is hidden, show the bag slots under the open bag window so bags can still be equipped and removed. Works with and without the Combine Bags option."] = "가방 바가 숨겨져 있는 동안 열린 가방 창 아래에 가방 칸을 보여 주어 가방을 계속 장착하고 뺄 수 있게 합니다. 가방 합치기 설정과 관계없이 작동합니다.", -- draft
	["Collapse Arrow"] = "접기 화살표", -- draft
	["An arrow beside the backpack folds the bag slots away so only the backpack shows; click it again to bring them back. While you hold an item they come out by themselves, so a new bag can be dropped into a slot. The game remembers which way you left it."] = "소지품 옆의 화살표가 가방 칸을 접어 소지품만 보이게 합니다. 다시 누르면 돌아옵니다. 아이템을 들고 있는 동안에는 저절로 나와 새 가방을 칸에 놓을 수 있습니다. 게임은 마지막 상태를 기억합니다.", -- draft
	["Chat"] = "대화", -- draft
	["Chat Notices"] = "대화 알림", -- draft
	["Lines MelloUI writes to chat on its own: a learned dungeon entrance, settings restored from the backup, hints. Replies to slash commands, and the notices you send to the chat (Send To Chat Instead), always show."] = "MelloUI가 스스로 대화에 쓰는 줄: 배운 던전 입구, 백업에서 복원한 설정, 도움말. 슬래시 명령의 응답과 대화로 보내는 알림(대신 대화로 보내기)은 항상 표시됩니다.", -- draft
	["Notices"] = "알림", -- draft
	["On-screen Notices"] = "화면 알림", -- draft
	["One short line in the upper third of the screen when MelloUI has news for you: a route set or finished, a service remembered, a dungeon's quests listed. It fades after a few seconds. Move it in Edit Layout."] = "MelloUI가 전할 소식이 있을 때 화면 위쪽 3분의 1에 나타나는 짧은 한 줄: 경로 설정 또는 완료, 기억된 서비스, 목록에 오른 던전 퀘스트. 몇 초 뒤 사라집니다. 레이아웃 편집에서 옮길 수 있습니다.", -- draft
	["Send To Chat Instead"] = "대신 대화로 보내기", -- draft
	["Write these lines in the chat instead of showing them on the screen. They show there even while Chat Notices is off."] = "이 줄을 화면에 띄우는 대신 대화에 씁니다. 대화 알림이 꺼져 있어도 그곳에 표시됩니다.", -- draft
	["Notice Sounds"] = "알림 소리", -- draft
	["A short chime with each notice: the map's tracking sound for a new destination (left out while the World Marker's own sound plays for it), a softer one when you arrive."] = "알림마다 짧은 종소리: 새 목적지에는 지도의 추적 소리(월드 마커 자체 소리가 날 때는 생략), 도착하면 더 부드러운 소리.", -- draft
	["Text Shade"] = "글자 그림자", -- draft
	["A soft dark shade behind the text MelloUI shows on the world, so it reads on bright ground: the zone name when you enter a new area (with its subzone and PvP lines), the game's messages in the middle of the screen (red errors, yellow quest progress, raid warnings and boss emotes), the Route's World Marker, the names on the unit frames (yours, your pet's, your targets' targets' and the party's) and on the nameplates, and the channel tags and links on the chat's parchment. No outline on the zone name and the messages (Outlined Text adds it back); the game's colours stay. Off: the game's own look, and no shade behind any of them."] = "MelloUI가 세상 위에 보여 주는 글자 뒤의 부드럽고 어두운 그림자로, 밝은 바탕에서도 읽히게 합니다: 새 지역에 들어갈 때의 지역 이름(하위 지역과 PvP 줄 포함), 화면 가운데의 게임 메시지(빨간 오류, 노란 퀘스트 진행, 공격대 경보와 우두머리 감정 표현), 경로의 월드 마커, 개체창(내 것, 소환수, 대상의 대상, 파티)과 이름표의 이름, 대화 양피지의 채널 태그와 링크. 지역 이름과 메시지에는 외곽선이 없습니다(외곽선 글자가 다시 넣음). 게임의 색은 유지됩니다. 끄기: 게임의 외형, 어디에도 그림자 없음.", -- draft
	["Outlined Text"] = "외곽선 글자", -- draft
	["Draw the text MelloUI shows on the world with an outline: the on-screen notice's lines, Combat Text's lines and the Gains lines, and, while Text Shade is on, the zone text and the game's messages in the middle of the screen. Off: soft text on a dark shade."] = "MelloUI가 세상 위에 보여 주는 글자에 외곽선을 그립니다: 화면 알림 줄, 전투 문자 줄과 획득 줄, 그리고 글자 그림자가 켜져 있는 동안 지역 글자와 화면 가운데의 게임 메시지. 끄기: 어두운 그림자 위의 부드러운 글자.", -- draft
	["Combat Text"] = "전투 문자", -- draft
	["Numbers Over Enemies"] = "적 위의 숫자", -- draft
	["The size of the numbers over the enemies and the ones you heal: the game's own, and Your Damage's when MelloUI draws them (one or the other shows). 1.0 is the game's size."] = "적과 치유 대상 위 숫자의 크기: 게임의 숫자와, MelloUI가 그릴 때의 내 피해 숫자(둘 중 하나가 보임). 1.0이 게임의 크기입니다.", -- draft
	["Bar Layout"] = "바 레이아웃", -- draft
	["Which Bar"] = "어느 바", -- draft
	["The bar the rows below set: its rows, icons, icon size and padding, saved into your active Edit Mode layout as Edit Mode saves them, once you let a slider go (out of combat). The game shows them after a reload: type /reload (MelloUI says so once). One of the game's preset layouts is copied first: you are asked once."] = "아래 줄들이 설정하는 바: 줄 수, 아이콘, 아이콘 크기, 간격을 슬라이더를 놓는 순간(전투 밖) 편집 모드가 저장하는 방식대로 현재 편집 모드 레이아웃에 저장합니다. 게임은 재시작 후에 보여 줍니다: /reload 를 입력하세요(MelloUI가 한 번 알려 줌). 먼저 게임의 기본 레이아웃 중 하나를 복사합니다: 한 번 묻습니다.", -- draft
	["Action Bar 1"] = "행동 단축바 1", -- draft
	["Action Bar 2"] = "행동 단축바 2", -- draft
	["Action Bar 3"] = "행동 단축바 3", -- draft
	["Action Bar 4"] = "행동 단축바 4", -- draft
	["Action Bar 5"] = "행동 단축바 5", -- draft
	["Action Bar 6"] = "행동 단축바 6", -- draft
	["Action Bar 7"] = "행동 단축바 7", -- draft
	["Action Bar 8"] = "행동 단축바 8", -- draft
	["Stance Bar"] = "태세 막대", -- draft
	["Pet Bar"] = "소환수 바", -- draft
	["Rows"] = "줄", -- draft
	["How many rows the bar's buttons stand in (columns, on a bar stood upright in Edit Mode)."] = "바의 버튼이 몇 줄로 서는지(편집 모드에서 세로로 세운 바라면 열 수).", -- draft
	["Icons"] = "아이콘", -- draft
	["How many of the bar's buttons show."] = "바의 버튼이 몇 개 보이는지.", -- draft
	["Icon Size"] = "아이콘 크기", -- draft
	["The size of the bar's buttons. 100% is the game's own size."] = "바 버튼의 크기. 100%가 게임의 크기입니다.", -- draft
	["Padding"] = "간격", -- draft
	["The room between the bar's buttons."] = "바 버튼 사이의 공간.", -- draft
	["The Bar's Shape"] = "바의 모양", -- draft
	["The bar as the rows above lay it out. Saved into your Edit Mode layout when you let a slider go (in a fight, when it ends); the bar itself changes after a reload."] = "위의 줄들이 배치하는 바. 슬라이더를 놓으면(전투 중이면 끝날 때) 편집 모드 레이아웃에 저장되며, 바 자체는 재시작 후 바뀝니다.", -- draft
	["Buff Layout"] = "강화 효과 레이아웃", -- draft
	["The size of your buff and debuff icons, in pixels: MelloUI's own rows while Your Buffs And Debuffs shows them, else the game's buff and debuff bars (saved into your Edit Mode layout in its own steps of 3 pixels, shown after a reload; 30 is the game's size)."] = "강화 및 약화 효과 아이콘의 크기(픽셀): 내 강화 및 약화 효과가 MelloUI의 줄을 보여 주는 동안은 그 줄, 아니면 게임의 강화 및 약화 효과 바(편집 모드 레이아웃에 3픽셀 단위로 저장, 재시작 후 표시; 30이 게임의 크기).", -- draft
	["Spacing"] = "간격", -- draft
	["The room between your buff and debuff icons."] = "강화 및 약화 효과 아이콘 사이의 공간.", -- draft
	["Per Row"] = "줄당 개수", -- draft
	["How many buffs stand in a row before the next row starts. Your debuffs start a row of their own (the game's debuff bar takes at most 16 in a row)."] = "다음 줄이 시작되기 전 한 줄에 놓이는 강화 효과 수. 약화 효과는 자기 줄에서 시작합니다(게임의 약화 효과 바는 한 줄에 최대 16개).", -- draft
	["Grow"] = "늘어나는 방향", -- draft
	["Which way a row of buffs grows from the first one."] = "강화 효과 줄이 첫 아이콘에서 어느 쪽으로 늘어나는지.", -- draft
	["New Rows"] = "새 줄", -- draft
	["Where the next row of buffs goes: under the first, or over it."] = "다음 강화 효과 줄이 갈 곳: 첫 줄 아래 또는 위.", -- draft
	["Down"] = "아래", -- draft
	["Up"] = "위", -- draft
	["Split Stack"] = "묶음 나누기", -- draft
	["Mouse Wheel Amount"] = "마우스 휠 수량", -- draft
	["In the box that splits a stack (Shift-click a stack), the mouse wheel changes the amount: up adds one, down takes one, ten at a time while you hold Shift."] = "묶음을 나누는 상자(묶음을 Shift-클릭)에서 마우스 휠로 수량을 바꿉니다: 위로 하나 더, 아래로 하나 빼기, Shift를 누르고 있으면 열 개씩.", -- draft
	["Half Button"] = "절반 버튼", -- draft
	["A ½ button at the left end of the split box's amount: click it and the amount is half the stack (191 makes 95). Buying in bundles at a merchant, it rounds down to whole bundles."] = "나누기 상자 수량 왼쪽 끝의 ½ 버튼: 누르면 수량이 묶음의 절반이 됩니다(191이면 95). 상인에게서 묶음 단위로 살 때는 묶음 단위로 내림합니다.", -- draft
	["Item Slots"] = "아이템 칸", -- draft
	["Quality Gems"] = "품질 보석", -- draft
	["A small gem in the top-left corner of every item in your bags, the bank and the guild bank, in the colour of the item's quality: grey for junk, white for common, then green, blue, purple and orange. Junk and better items stand out at a glance. While the game shows its own mark in that corner (the junk coin at a merchant, the upgrade arrow, the exclamation mark on an item that starts a quest, the quality badge on a crafting reagent), the gem moves to the top-right corner. One switch for all three windows."] = "가방, 은행, 길드 은행의 모든 아이템 왼쪽 위 구석에 아이템 품질 색의 작은 보석: 잡동사니는 회색, 일반은 흰색, 그다음 녹색, 파랑, 보라, 주황. 잡동사니와 더 좋은 아이템이 한눈에 보입니다. 게임이 그 구석에 자체 표시(상인의 잡동사니 동전, 개선 화살표, 퀘스트를 시작하는 아이템의 느낌표, 제작 재료의 품질 휘장)를 보여 주는 동안에는 보석이 오른쪽 위 구석으로 옮겨 갑니다. 세 창 모두에 스위치 하나.", -- draft
	["Grey Out Junk"] = "잡동사니 회색 처리", -- draft
	["Junk (grey quality) items show grey in your bags, the bank and the guild bank, so they stand apart from what you keep. One switch for all three windows."] = "잡동사니(회색 품질) 아이템이 가방, 은행, 길드 은행에서 회색으로 보여 간직할 물건과 구분됩니다. 세 창 모두에 스위치 하나.", -- draft
	["Level Up"] = "레벨 상승", -- draft
	["When you gain a level, a light runs along the experience bar and the on-screen notice says your new level and, with the Quest List, how many quests it opened in your zone (their givers pop onto the world map the next time it shows them). With the painted reskin, the number in your player frame's level circle also turns over with a ring of light. Not with Reduce Motion: then only the notice."] = "레벨이 오르면 빛이 경험치 막대를 따라 달리고, 화면 알림이 새 레벨과, 퀘스트 리스트가 있으면 그 레벨로 지역에 열린 퀘스트 수를 알려 줍니다(퀘스트 제공자는 다음에 세계 지도가 보여 줄 때 나타남). 페인팅 스킨에서는 플레이어 창 레벨 원 안의 숫자도 빛의 고리와 함께 넘어갑니다. 움직임 줄이기에서는 아님: 알림만.", -- draft
	["XP Gain"] = "경험치 획득", -- draft
	["When you gain experience, the stretch of the experience bar just gained lights up while a light runs along it to the new end. Not with Reduce Motion."] = "경험치를 얻으면 방금 얻은 경험치 막대 구간이 밝아지고 빛이 새 끝까지 달립니다. 움직임 줄이기에서는 아님.", -- draft
	-- Stats
	["Small coloured FPS and latency readout in the bottom right corner."] = "오른쪽 아래 구석의 작은 색상 FPS 및 지연 시간 표시.", -- draft
	["Frames per second and latency in the corner. Blame the server with confidence."] = "구석의 초당 프레임과 지연 시간. 자신 있게 서버 탓을 하세요.", -- draft
	["Values"] = "값", -- draft
	["Show FPS"] = "FPS 표시", -- draft
	["Frames per second."] = "초당 프레임.", -- draft
	["Show Latency"] = "지연 시간 표시", -- draft
	["Home latency in milliseconds."] = "밀리초 단위의 로컬 지연 시간.", -- draft
	["Show World Latency Too"] = "월드 지연 시간도 표시", -- draft
	["Also show the world server latency next to the home latency."] = "로컬 지연 시간 옆에 월드 서버 지연 시간도 표시합니다.", -- draft
	["Look"] = "외형", -- draft
	["Distance from the right edge of the screen."] = "화면 오른쪽 가장자리로부터의 거리.", -- draft
	["Distance from the bottom edge of the screen."] = "화면 아래쪽 가장자리로부터의 거리.", -- draft
	["Update Interval"] = "갱신 간격", -- draft
	-- Vendor
	["Vendor"] = "상인", -- draft
	["Automatically repair your gear and sell junk items when visiting a merchant."] = "상인을 방문하면 장비를 자동으로 수리하고 잡동사니를 팝니다.", -- draft
	["Sell the grey, mend the steel. Every merchant visit handled before the window opens."] = "회색은 팔고 강철은 고치세요. 상인 방문을 창이 열리기 전에 처리합니다.", -- draft
	["Repair"] = "수리", -- draft
	["Auto Repair"] = "자동 수리", -- draft
	["Repair all equipped and carried items when a merchant that can repair is opened."] = "수리할 수 있는 상인을 열면 착용하고 지닌 모든 아이템을 수리합니다.", -- draft
	["Use Guild Funds"] = "길드 자금 사용", -- draft
	["Pay repairs from the guild bank when allowed. Falls back to your own gold if the guild cannot cover the cost."] = "허용되면 길드 은행에서 수리비를 냅니다. 길드가 비용을 감당할 수 없으면 내 골드를 씁니다.", -- draft
	["Selling"] = "판매", -- draft
	["Auto Sell Junk"] = "잡동사니 자동 판매", -- draft
	["Sell all grey quality items in your bags when a merchant is opened."] = "상인을 열면 가방 안의 회색 품질 아이템을 모두 팝니다.", -- draft
	["Report In Chat"] = "대화에 보고", -- draft
	["Print the repair cost, the gold gained from selling junk and what Restock bought for you."] = "수리비, 잡동사니 판매로 번 골드, 재보충이 대신 산 것을 출력합니다.", -- draft
	-- Services
	["Services"] = "서비스", -- draft
	["Service icons under the minimap that route you to the nearest repair, mailbox, innkeeper, flight master, auction house, bank, trainer, barber or transmogrifier."] = "가장 가까운 수리, 우체통, 여관주인, 비행 조련사, 경매장, 은행, 전문가, 미용사, 형상변환사로 안내하는 미니맵 아래의 서비스 아이콘.", -- draft
	["Repair, mailbox, innkeeper, bank... the nearest one is a click under the minimap."] = "수리, 우체통, 여관주인, 은행... 가장 가까운 곳이 미니맵 아래 클릭 한 번.", -- draft
	["Icon Bar Under The Minimap"] = "미니맵 아래 아이콘 바", -- draft
	["Service buttons under the minimap; they move with the minimap in Edit Mode. Groups: one row of group buttons as wide as the map; click one to open its services with their distances, then click a service to route to the nearest one by road. All Buttons: two rows with an icon for every service; click one to route there. Right-click stops the route. A grey button has none known on this continent yet. With the square minimap and \"Merge With Services\" on (the Minimap page, Services), the buttons sit inside the minimap's frame."] = "미니맵 아래의 서비스 버튼. 편집 모드에서 미니맵과 함께 움직입니다. 그룹: 지도 폭만 한 그룹 버튼 한 줄. 하나를 누르면 서비스와 거리가 열리고, 서비스를 누르면 도로를 따라 가장 가까운 곳으로 경로를 잡습니다. 모든 버튼: 서비스마다 아이콘이 있는 두 줄. 하나를 누르면 경로를 잡습니다. 오른쪽 클릭은 경로를 멈춥니다. 회색 버튼은 이 대륙에서 아직 아는 곳이 없습니다. 사각 미니맵에 \"서비스와 합치기\"가 켜져 있으면(미니맵 페이지, 서비스) 버튼이 미니맵 테두리 안에 놓입니다.", -- draft
	["Button Layout"] = "버튼 배치", -- draft
	["Groups: one row of buttons as wide as the map (Travel, Trade, Repair, Trainers, Looks, Errands, and AddOns while your addons have minimap buttons). Click a group for a small list of its services, each with the distance to the nearest one; click a service to route there. Repair routes at once. Errands lists your reminders (Restock, Mail, Repair Gear, Trainer) and how each stands; click one to route to the nearest place for it. All Buttons: two rows with an icon for every service."] = "그룹: 지도 폭만 한 버튼 한 줄(여행, 거래, 수리, 전문가, 외형, 볼일, 그리고 애드온에 미니맵 버튼이 있으면 애드온). 그룹을 누르면 서비스의 작은 목록이 가장 가까운 곳까지의 거리와 함께 나옵니다. 서비스를 누르면 경로를 잡습니다. 수리는 바로 경로를 잡습니다. 볼일은 알림(재보충, 우편, 장비 수리, 전문가)과 각 상태를 보여 주며, 하나를 누르면 가장 가까운 장소로 경로를 잡습니다. 모든 버튼: 서비스마다 아이콘이 있는 두 줄.", -- draft
	["Groups"] = "그룹", -- draft
	["All Buttons"] = "모든 버튼", -- draft
	["AddOns Group"] = "애드온 그룹", -- draft
	["Your addons' minimap buttons (Questie and the others that put a round button on the minimap's edge) taken off the minimap and gathered into one more group in the Services row, AddOns: click it for a list of them. A click on an addon there is that addon's own (left, right or middle), and pointing at it shows its own tooltip. Only with Button Layout's Groups. Off: the buttons go back on the minimap."] = "애드온의 미니맵 버튼(Questie처럼 미니맵 가장자리에 둥근 버튼을 다는 것들)을 미니맵에서 떼어 서비스 줄의 그룹 하나, 애드온으로 모읍니다: 누르면 목록이 나옵니다. 거기서 애드온을 누르면 그 애드온 자체의 클릭(왼쪽, 오른쪽, 가운데)이고, 가리키면 그 애드온의 툴팁이 나옵니다. 버튼 배치가 그룹일 때만. 끄기: 버튼이 미니맵으로 돌아갑니다.", -- draft
	["Bar Distance From The Minimap"] = "미니맵과 바 사이 거리", -- draft
	["How far under the minimap the buttons sit. Not used while they are merged into the square minimap's frame."] = "버튼이 미니맵 아래로 얼마나 떨어져 있는지. 사각 미니맵 테두리에 합쳐져 있는 동안에는 쓰이지 않습니다.", -- draft
	["Round Icons"] = "원형 아이콘", -- draft
	["Show the service icons as round medallions in a round rim instead of squares."] = "서비스 아이콘을 사각형 대신 둥근 테 안의 원형 메달로 표시합니다.", -- draft
	["Trays Slide Out"] = "서랍처럼 열기", -- draft
	["A group's list slides out from the minimap column like a drawer when you click its button, its rows one after another, and slides back in as it closes. Not with Reduce Motion: then it shows at once."] = "그룹 버튼을 누르면 목록이 미니맵 열에서 서랍처럼 줄줄이 미끄러져 나오고, 닫힐 때 다시 들어갑니다. 움직임 줄이기에서는 아님: 바로 나타납니다.", -- draft
	["Minimap Button"] = "미니맵 버튼", -- draft
	["Also show a round button on the minimap's edge that opens the list of the nearest services; drag it to move it, right-click it to stop the route. /services opens the same list."] = "미니맵 가장자리에 가장 가까운 서비스 목록을 여는 둥근 버튼도 표시합니다. 끌어서 옮기고, 오른쪽 클릭으로 경로를 멈춥니다. /services 도 같은 목록을 엽니다.", -- draft
	-- Reminders
	["Reminders"] = "알림", -- draft
	["A round button by your portrait for errands: supplies low (Restock), new mail, gear to repair, a trainer with something new. Click it to route there. Off, none of the four shows; the Widgets' portrait reminders keep their own switches."] = "볼일을 알리는 초상화 옆 둥근 버튼: 보급품 부족(재보충), 새 우편, 수리할 장비, 새로 배울 것이 있는 전문가. 누르면 경로를 잡습니다. 끄면 네 가지 모두 표시되지 않습니다. 위젯의 초상화 알림은 각자의 스위치를 유지합니다.", -- draft
	["Supplies, mail, repairs and training: a gentle nudge beside your portrait, never a nag."] = "보급품, 우편, 수리, 훈련: 잔소리가 아니라 초상화 옆의 가벼운 귀띔.", -- draft
	["New Mail"] = "새 우편", -- draft
	["Remind you when mail is waiting for you. It goes once you open a mailbox, and comes back only for mail that arrives after."] = "우편이 기다리고 있으면 알립니다. 우체통을 열면 사라지고, 그 뒤에 도착한 우편이 있을 때만 다시 나옵니다.", -- draft
	["Repair Gear"] = "장비 수리", -- draft
	["Remind you when your gear is wearing out. Broken gear goes to the top of the list."] = "장비가 닳고 있으면 알립니다. 부서진 장비가 목록 맨 위로 갑니다.", -- draft
	["Remind At"] = "알림 기준", -- draft
	["Remind you once your most worn piece of gear is down to this much durability."] = "가장 닳은 장비의 내구도가 이만큼 내려가면 알립니다.", -- draft
	["Trainer"] = "전문가", -- draft
	["Remind you when a trainer has something new for you."] = "전문가에게 새로 배울 것이 있으면 알립니다.", -- draft
	["Class Spells"] = "직업 주문", -- draft
	["When you reach a level with new spells at your class trainer. It stays until you have learned them; each visit to your class trainer tells MelloUI when the next ones come, and before your first visit it goes by the levels trainers teach at."] = "직업 전문가에게 새 주문이 있는 레벨에 도달하면. 배울 때까지 남아 있습니다. 직업 전문가를 찾을 때마다 MelloUI가 다음 주문이 언제인지 알게 되며, 첫 방문 전에는 전문가가 가르치는 레벨을 기준으로 합니다.", -- draft
	["Profession Ranks"] = "전문 기술 등급", -- draft
	["When one of your professions can learn its next rank at a trainer: Journeyman, Expert or Artisan."] = "전문 기술 하나가 전문가에게서 다음 등급을 배울 수 있을 때: 수습, 숙련, 전문.", -- draft
	["Stay Up In Rest Areas"] = "휴식 지역에서 유지", -- draft
	["In an inn or a city, and in a town like Sentinel Hill, every reminder stays until it is done (a mailbox opened, the spells or the rank learned ...) or you leave; Not now there waits until you next enter one."] = "여관이나 도시, 그리고 감시의 언덕 같은 마을에서는 모든 알림이 완료되거나(우체통 열기, 주문이나 등급 배우기 ...) 떠날 때까지 남아 있습니다. 그곳에서 나중에는 다음에 다시 들어올 때까지 기다립니다.", -- draft
	["Widget"] = "위젯", -- draft
	["Place"] = "위치", -- draft
	["Where the reminder button sits beside your portrait. With the player frame hidden it keeps a place of its own, which you can move in Edit Layout."] = "초상화 옆 알림 버튼의 위치. 플레이어 창이 숨겨져 있으면 자기 자리를 가지며, 레이아웃 편집에서 옮길 수 있습니다.", -- draft
	["Left of the portrait"] = "초상화 왼쪽", -- draft
	["Above the portrait"] = "초상화 위", -- draft
	["Right of the portrait"] = "초상화 오른쪽", -- draft
	["Glow"] = "빛", -- draft
	["The soft glow around the button: a gentle pulse for a few seconds, then steady; always steady; or none. It brightens when you are close to where the reminder sends you."] = "버튼 둘레의 부드러운 빛: 몇 초간 부드럽게 맥동한 뒤 고정, 항상 고정, 또는 없음. 알림이 안내하는 곳 가까이 가면 밝아집니다.", -- draft
	["Pulse, then steady"] = "맥동 후 고정", -- draft
	["Steady"] = "고정", -- draft
	["Show For"] = "표시 시간", -- draft
	["How long a new reminder stays before it tucks itself away. It stays while your pointer is on it."] = "새 알림이 접혀 들어가기 전까지 머무는 시간. 마우스 포인터가 위에 있는 동안은 남아 있습니다.", -- draft
	["Lock The Widgets"] = "위젯 잠금", -- draft
	["Keep the widget column (Voice Over, loot rolls, the corpse run and the rest) where it is: Edit Layout shows its plate but does not move it. Voice Over's padlock sets this too."] = "위젯 열(Voice Over, 전리품 주사위, 시체 찾기 등)을 제자리에 고정합니다: 레이아웃 편집에서 판은 보이지만 움직이지 않습니다. Voice Over의 자물쇠도 이것을 설정합니다.", -- draft
	["Most Widgets Shown"] = "최대 위젯 수", -- draft
	["How many widgets the column shows at once. The rest wait in a slim \"+2 more\" row on top; a click there lists them. Loot rolls, summons, resurrect offers and ready checks always show, and Voice Over keeps the bottom place."] = "열이 한 번에 보여 주는 위젯 수. 나머지는 위쪽의 얇은 \"+2개 더\" 줄에서 기다리며, 누르면 목록이 나옵니다. 전리품 주사위, 소환, 부활 제안, 준비 확인은 항상 보이며 Voice Over는 맨 아래 자리를 지킵니다.", -- draft
	-- Restock
	["Restock"] = "재보충", -- draft
	["Keeps drink, food, ammunition and reagents in your bags: a reminder when one runs low (with Reminders on), and at a shop a list of what to buy, bought only when you click Buy."] = "가방에 음료, 음식, 탄환, 재료를 유지합니다: 하나가 부족하면 알림(알림이 켜져 있을 때), 상점에서는 살 목록. 구매를 누를 때만 삽니다.", -- draft
	["Water, bread and arrows, topped up before they run out."] = "물, 빵, 화살을 떨어지기 전에 채워 둡니다.", -- draft
	["Remind Below"] = "알림 기준 미만", -- draft
	["You are reminded when a line drops below this share of its amount: at 50 %, a line of 20 water reminds you at 9. At a shop it is bought back up to the full amount. The reminder needs Reminders on; the Restock List marks the low lines either way."] = "줄이 자기 수량의 이 비율 아래로 떨어지면 알립니다: 50 %이면 물 20개 줄은 9개에서 알립니다. 상점에서는 전체 수량까지 다시 삽니다. 알림은 알림이 켜져 있어야 하며, 재보충 목록은 어느 쪽이든 부족한 줄을 표시합니다.", -- draft
	["Shopping List At The Shop"] = "상점 구매 목록", -- draft
	["At a merchant who sells what you are low on, a small list beside the shop window: each item, how many and the price, and the total. Nothing is bought until you click Buy."] = "부족한 것을 파는 상인에게서, 상점 창 옆의 작은 목록: 각 아이템, 수량과 가격, 합계. 구매를 누르기 전에는 아무것도 사지 않습니다.", -- draft
	["Restock List"] = "재보충 목록", -- draft
	["What to keep in your bags and how many. Each character has its own list; a new one starts with suggestions for its class. Also /restock."] = "가방에 둘 것과 수량. 캐릭터마다 목록이 있으며, 새 목록은 그 직업의 추천으로 시작합니다. /restock 도 됩니다.", -- draft
	["Edit"] = "편집", -- draft
	-- Widgets
	["Widgets"] = "위젯", -- draft
	["Small live widgets in one column: loot rolls, the way back to your corpse, timed quests, summons, resurrect offers, ready checks, whispers, your pet, the auction house, crafting batches, profession cooldowns, quest items and a healer drinking. And more reminders by your portrait: bags, talents, Well Fed, weapon poisons and oils, your buffs."] = "한 열에 모인 작은 실시간 위젯: 전리품 주사위, 시체로 돌아가는 길, 시간제한 퀘스트, 소환, 부활 제안, 준비 확인, 귓속말, 소환수, 경매장, 연속 제작, 전문 기술 재사용 대기시간, 퀘스트 아이템, 물 마시는 치유사. 그리고 초상화 옆의 알림 더: 가방, 특성, 포만감, 무기 독과 오일, 내 강화 효과.", -- draft
	["What needs you now, in one small column."] = "지금 나를 필요로 하는 것을 작은 열 하나에.", -- draft
	["In The Column"] = "열 안", -- draft
	["Loot Rolls"] = "전리품 주사위", -- draft
	["A roll in a group: the item in its quality colour, a ring for the time left, and Need, Greed and Pass on hover. The count is the rolls waiting. The game's own roll window stays out of sight meanwhile (with the Gamepad UI it stays)."] = "파티의 주사위: 품질 색의 아이템, 남은 시간 고리, 가리키면 입찰, 차비, 포기. 숫자는 기다리는 주사위 수입니다. 그동안 게임의 주사위 창은 보이지 않습니다(게임패드 UI에서는 남음).", -- draft
	["Corpse Run"] = "시체 찾기", -- draft
	["As a ghost: how far your body is and which way, and a ring until you can come back. Click it for the way there; at your body, Resurrect. The game's own Resurrect popup is see-through and click-through meanwhile."] = "유령일 때: 시체까지의 거리와 방향, 돌아갈 수 있을 때까지의 고리. 누르면 길을 보여 줍니다. 시체에 닿으면 부활. 그동안 게임의 부활 팝업은 투명하고 클릭이 통과합니다.", -- draft
	["Timed Quests"] = "시간제한 퀘스트", -- draft
	["A quest with a time limit: a ring for its whole time and the time left."] = "시간제한이 있는 퀘스트: 전체 시간의 고리와 남은 시간.", -- draft
	["Summons"] = "소환", -- draft
	["Someone summons you: where to, the time left, and Accept or Decline on hover. The game's own popup is see-through and click-through meanwhile."] = "누군가 나를 소환합니다: 어디로, 남은 시간, 가리키면 수락 또는 거절. 그동안 게임의 팝업은 투명하고 클릭이 통과합니다.", -- draft
	["Resurrect Offers"] = "부활 제안", -- draft
	["Someone offers to resurrect you: the time left, and Accept or Decline on hover. The game's own popup is see-through and click-through meanwhile."] = "누군가 부활을 제안합니다: 남은 시간, 가리키면 수락 또는 거절. 그동안 게임의 팝업은 투명하고 클릭이 통과합니다.", -- draft
	["Ready Checks"] = "준비 확인", -- draft
	["The leader's ready check and its time, with Ready and Not Ready on hover (a click on it: Ready). The game's own box stays away meanwhile (with the Gamepad UI it stays); its alert sound and the taskbar flash still come."] = "파티장의 준비 확인과 그 시간, 가리키면 준비와 준비되지 않음(누르면 준비). 그동안 게임의 상자는 나오지 않습니다(게임패드 UI에서는 남음). 경고음과 작업 표시줄 깜빡임은 그대로 옵니다.", -- draft
	["Threat"] = "위협", -- draft
	["In a group fight, only when it matters: close to pulling your target (\"Ease off\") or with it on you (\"Aggro\"), and for a tank the mobs not on you. The ring is your threat against the pull; point at it for the group's threat on your target."] = "파티 전투에서 중요할 때만: 대상을 끌어오기 직전(\"살살\")이거나 이미 나에게 붙었을 때(\"어그로\"), 방어 전담에게는 나에게 붙지 않은 적. 고리는 끌어오기 기준 대비 내 위협 수준이며, 가리키면 대상에 대한 파티의 위협 수준이 보입니다.", -- draft
	["Whispers"] = "귓속말", -- draft
	["A new whisper: the sender in their class colour, the last line and how many are unread. Reply opens their whisper window. Needs Chat's Whisper Popup Window."] = "새 귓속말: 직업 색의 보낸 사람, 마지막 줄, 읽지 않은 개수. 답장은 그 사람의 귓속말 창을 엽니다. 대화의 귓속말 팝업 창이 필요합니다.", -- draft
	["Hunter Pet"] = "사냥꾼 소환수", -- draft
	["Your pet is not happy: its face, a ring for its happiness, and Feed Pet on hover (out of combat)."] = "소환수가 불만족합니다: 얼굴, 만족도 고리, 가리키면 소환수 먹이 주기(전투 밖).", -- draft
	["Auction House"] = "경매장", -- draft
	["Outbid, sold, won and expired at the auction house, in one list. Click it for the way to the nearest mailbox."] = "경매장의 상회 입찰, 판매, 낙찰, 만료를 한 목록에. 누르면 가장 가까운 우체통으로 가는 길.", -- draft
	["Crafting"] = "제작", -- draft
	["A batch you craft: which one of how many, a ring for each item, and Stop on hover."] = "연속 제작: 몇 개 중 몇 번째, 아이템마다 고리, 가리키면 중지.", -- draft
	["Profession Cooldowns"] = "전문 기술 재사용 대기시간", -- draft
	["A profession cooldown ready again (a transmute, mooncloth, the salt shaker). MelloUI learns it when you open that profession."] = "전문 기술 재사용 대기시간이 다시 준비됨(변환, 달빛 옷감, 소금 통). 그 전문 기술을 열면 MelloUI가 알게 됩니다.", -- draft
	["Quest Items"] = "퀘스트 아이템", -- draft
	["In a quest's objective area, with the quest's item in your bags: the item, a ring for the objective's progress and how many you carry. Click it to use the item (out of combat: it folds away in a fight)."] = "퀘스트 목표 지역에서 가방에 퀘스트 아이템이 있으면: 아이템, 목표 진행 고리, 가진 개수. 누르면 아이템을 사용합니다(전투 밖: 전투 중에는 접힘).", -- draft
	["Healer Drinking"] = "물 마시는 치유사", -- draft
	["When you tank a group, between pulls: a healer of your group is drinking, so wait before the next pull. It goes when they stop or a fight starts. The game keeps party mana hidden from addons, so it shows their drinking, not their mana."] = "파티의 방어 전담일 때 전투 사이: 파티의 치유사가 물을 마시고 있으니 다음 몰이 전에 기다리세요. 그가 멈추거나 전투가 시작되면 사라집니다. 게임은 파티의 마나를 애드온에게 숨기므로 마나가 아니라 물 마시는 것을 보여 줍니다.", -- draft
	["Rare Alert"] = "희귀 경보", -- draft
	["A rare or rare elite nearby, seen on the minimap, as a nameplate, as your target or under the mouse: its face, its name and how far it is, glowing as it comes up. Click its face to target it (out of combat); Lead Me There shows the way to where the minimap has it."] = "근처의 희귀 또는 희귀 정예, 미니맵, 이름표, 대상, 마우스 아래에서 발견: 얼굴, 이름, 거리, 나타날 때 빛남. 얼굴을 누르면 대상으로 잡습니다(전투 밖). 길 안내는 미니맵이 표시한 곳으로 가는 길을 보여 줍니다.", -- draft
	["Rare Alert Sound"] = "희귀 경보 소리", -- draft
	["Play a sound when a rare is spotted."] = "희귀가 발견되면 소리를 냅니다.", -- draft
	["By The Portrait"] = "초상화 옆", -- draft
	["Bags Almost Full"] = "가방이 거의 가득 참", -- draft
	["Remind you when your bags are almost full; it stays, in a fight too, until you make room. Click it for the way to the nearest vendor."] = "가방이 거의 가득 차면 알리며, 공간을 만들 때까지 전투 중에도 남아 있습니다. 누르면 가장 가까운 상인으로 가는 길.", -- draft
	["Free Slots"] = "빈 칸", -- draft
	["Remind you once this many free bag slots or fewer are left."] = "빈 가방 칸이 이만큼 이하로 남으면 알립니다.", -- draft
	["Talent Points"] = "특성 점수", -- draft
	["Remind you when you have talent points to spend."] = "쓸 특성 점수가 있으면 알립니다.", -- draft
	["Well Fed Ending"] = "포만감 종료", -- draft
	["Remind you when Well Fed has two minutes left."] = "포만감이 2분 남으면 알립니다.", -- draft
	["Weapon Poisons & Oils"] = "무기 독과 오일", -- draft
	["Remind you when a poison, an oil or a sharpening stone has run out on a weapon, or has two minutes left, while you carry one to put it back on. It stays until it is back on, in fights too; click it to put it back on (out of combat)."] = "무기의 독, 오일, 숫돌이 다 되었거나 2분 남았을 때, 다시 바를 것을 가지고 있으면 알립니다. 다시 바를 때까지 전투 중에도 남아 있으며, 누르면 다시 바릅니다(전투 밖).", -- draft
	["Your Buffs"] = "내 강화 효과", -- draft
	["Remind you when one of your own buffs is missing on you: Arcane Intellect and a mage's armor, Fortitude, Inner Fire and Divine Spirit, Mark of the Wild, a warlock's armor. Only buffs you can cast. It stays until the buff is back, in fights too (the game hides buffs in a fight, so one lost there shows after it); click it to cast (out of combat)."] = "내 강화 효과 중 하나가 나에게 없으면 알립니다: 신비한 지능과 마법사의 갑옷, 인내, 내면의 열정과 천상의 정신, 야생의 징표, 흑마법사의 갑옷. 내가 걸 수 있는 강화 효과만. 효과가 돌아올 때까지 전투 중에도 남아 있습니다(게임은 전투 중 강화 효과를 숨기므로 전투 중 사라진 것은 전투 후에 보임). 누르면 겁니다(전투 밖).", -- draft
	["Your Buffs On The Group"] = "파티의 내 강화 효과", -- draft
	["Remind you when people in your group are missing a buff you can cast (Arcane Intellect and Divine Spirit only on those who use mana); point at it for their names. It stays until they have it, in fights too; click it to cast it on them, one by one (out of combat)."] = "파티원에게 내가 걸 수 있는 강화 효과가 없으면 알립니다(신비한 지능과 천상의 정신은 마나를 쓰는 사람만). 가리키면 이름이 보입니다. 모두 받을 때까지 전투 중에도 남아 있으며, 누르면 한 명씩 걸어 줍니다(전투 밖).", -- draft
	-- Discard
	["Discard"] = "버리기", -- draft
	["A button on the bag and loot windows that throws away your cheapest grey or white junk to free a slot (sells it at a vendor)."] = "가방과 전리품 창에서 가장 싼 회색이나 흰색 잡동사니를 버려 칸을 비우는 버튼(상인 앞에서는 팝니다).", -- draft
	["Full bags? The cheapest junk makes room, never anything worth keeping."] = "가방이 가득? 가장 싼 잡동사니가 자리를 비우고, 간직할 만한 것은 절대 건드리지 않습니다.", -- draft
	["Discard Button"] = "버리기 버튼", -- draft
	["A button on the bag window that frees a slot: it throws away the grey or white junk item worth least (at a vendor it sells it). Never food, drink, potions, scrolls, conjured items, crafting materials, quest items, reagents, ammunition, keys, white gear or anything on your Restock list. A white item asks first."] = "칸을 비우는 가방 창의 버튼: 가장 값싼 회색이나 흰색 잡동사니를 버립니다(상인 앞에서는 팝니다). 음식, 음료, 물약, 두루마리, 창조된 아이템, 제작 재료, 퀘스트 아이템, 재료, 탄환, 열쇠, 흰색 장비, 재보충 목록의 아이템은 절대 버리지 않습니다. 흰색 아이템은 먼저 묻습니다.", -- draft
	["Discard Button On Loot"] = "전리품의 버리기 버튼", -- draft
	["The same button on the loot window. It frees a slot only when something you are looting is worth more than what it would throw away."] = "전리품 창의 같은 버튼. 줍는 것이 버릴 것보다 값질 때만 칸을 비웁니다.", -- draft
	["Never Throw Away Items Worth"] = "버리지 않을 아이템 가치", -- draft
	["In silver: a stack worth this or more is never thrown away (selling it at a vendor still is). 100 silver = 1 gold."] = "실버 단위: 이 이상 가치의 묶음은 절대 버리지 않습니다(상인에게 파는 것은 됨). 100실버 = 1골드.", -- draft
	-- Gains
	["Gains"] = "획득", -- draft
	["Short lines beside your character show what you just gained: a skill point, the items you loot or receive, and what you buy. You can move them in Edit Layout."] = "캐릭터 옆의 짧은 줄이 방금 얻은 것을 보여 줍니다: 기술 점수, 줍거나 받은 아이템, 산 것. 레이아웃 편집에서 옮길 수 있습니다.", -- draft
	["Every skill point and every new item, told softly beside your character, then gone."] = "기술 점수 하나, 새 아이템 하나마다 캐릭터 옆에 조용히 알리고 사라집니다.", -- draft
	["Show"] = "표시", -- draft
	["Skill Ups"] = "기술 상승", -- draft
	["A line when one of your skills goes up: weapon skills, Defense, professions, secondary skills and languages."] = "기술이 오를 때 한 줄: 무기 기술, 방어, 전문 기술, 보조 기술, 언어.", -- draft
	["Show Skill Values"] = "기술 값 표시", -- draft
	["The skill's new value and its cap after its name, such as 57 / 80."] = "이름 뒤에 기술의 새 값과 한도, 예: 57 / 80.", -- draft
	["Looted & Received Items"] = "주운 아이템과 받은 아이템", -- draft
	["A line for each item that comes into your bags: loot, quest rewards, crafted items, mail and trades. Moving items between your bags, the bank and your gear never counts."] = "가방에 들어오는 아이템마다 한 줄: 전리품, 퀘스트 보상, 제작한 아이템, 우편, 거래. 가방, 은행, 장비 사이 이동은 세지 않습니다.", -- draft
	["Bought Items"] = "산 아이템", -- draft
	["A line for what you buy from a merchant, buybacks too, marked as bought."] = "상인에게서 산 것(재매입 포함)마다 구매로 표시한 줄.", -- draft
	["Junk Items"] = "잡동사니", -- draft
	["Also show junk (grey) items. Off: they are left out."] = "잡동사니(회색) 아이템도 표시합니다. 끄기: 빠집니다.", -- draft
	["Money"] = "돈", -- draft
	["A line when your money goes up: loot, quest rewards, sales, mail and trades, with the game's coins. Several gains in a row add up on one line. Spending makes no line."] = "돈이 늘 때 한 줄: 전리품, 퀘스트 보상, 판매, 우편, 거래, 게임의 동전과 함께. 연이은 획득은 한 줄로 합산됩니다. 지출은 줄을 만들지 않습니다.", -- draft
	["Currencies"] = "화폐", -- draft
	["A line for the other currencies you gain (honor, tokens, marks), with the currency's own icon."] = "얻은 다른 화폐(명예, 증표, 징표)마다 그 화폐 아이콘과 함께 한 줄.", -- draft
	["Item Names In Quality Colour"] = "품질 색 아이템 이름", -- draft
	["Item names in their quality colour (green, blue, purple) beside the quality gem. Blue and purple read less well over bright ground. Off: the names in the text colour."] = "품질 보석 옆에 품질 색(녹색, 파랑, 보라)의 아이템 이름. 파랑과 보라는 밝은 바탕에서 덜 읽힙니다. 끄기: 글자 색의 이름.", -- draft
	["Lines"] = "줄", -- draft
	["How long each line stays before it fades. Gaining the same skill or item again adds to its line and starts it over."] = "각 줄이 사라지기 전 머무는 시간. 같은 기술이나 아이템을 다시 얻으면 그 줄에 더해지고 다시 시작합니다.", -- draft
	-- Meter
	["Damage Meter"] = "미터기", -- draft
	["MelloUI's damage meter in place of the game's: three numbers by every frame (this fight, this run, healing), a race bar for the group in a fight, a summary after it and a Fight History window. The game's own damage meter is switched off while it is on, and comes back as you had it when it is off."] = "게임의 것 대신 MelloUI의 피해량 측정기: 모든 창 옆의 세 숫자(이번 전투, 이번 던전, 치유), 전투 중 파티 경주 막대, 전투 후 요약, 전투 기록 창. 켜져 있는 동안 게임의 피해량 측정기는 꺼지고, 끄면 원래대로 돌아옵니다.", -- draft
	["How the fight went, where you already look."] = "전투가 어땠는지, 이미 보고 있는 곳에서.", -- draft
	["Your Values"] = "내 값", -- draft
	["Three numbers on top of your frame: the sword this fight's damage per second, the hourglass this run's, the cross your healing per second. Live in a fight, the last fight's after it. Move them in Edit Layout (Your Values)."] = "내 창 위의 세 숫자: 칼은 이번 전투의 초당 피해, 모래시계는 이번 던전의 것, 십자는 초당 치유. 전투 중에는 실시간, 전투 후에는 마지막 전투의 값. 레이아웃 편집(내 값)에서 옮기세요.", -- draft
	["Party Values"] = "파티 값", -- draft
	["The same three numbers on top of each party frame. To make room, the game's own Show Party Pets setting is switched on while this is on (the party frames stand a little further apart, and party pets show under them); your own setting comes back when it is off. With raid-style party frames: On Raid-Style Frames."] = "각 파티 창 위의 같은 세 숫자. 자리를 만들기 위해 켜져 있는 동안 게임의 파티 소환수 표시 설정을 켭니다(파티 창 사이가 조금 벌어지고 파티 소환수가 그 아래 보임). 끄면 원래 설정이 돌아옵니다. 공격대 형태 파티 창에서는: 공격대 형태 창에서.", -- draft
	["On Raid-Style Frames"] = "공격대 형태 창에서", -- draft
	["A small DPS or healing number on the right of each raid-style or raid frame, beside the health. In a fight, players MelloUI cannot tell apart stay empty until it ends. Point at a frame for all three numbers."] = "각 공격대 형태 창이나 공격대 창 오른쪽, 생명력 옆의 작은 DPS 또는 치유 숫자. 전투 중 MelloUI가 구분할 수 없는 플레이어는 전투가 끝날 때까지 비어 있습니다. 창을 가리키면 세 숫자가 모두 보입니다.", -- draft
	["Race Bar"] = "경주 막대", -- draft
	["In a fight, one line for the group: the top player at its right end with their value, everyone else a class icon at their share of the top, you the bigger icon with the line filled up to you in your class colour. It fades in when the fight starts and out when it ends. The pointer on it lists everyone. Move it in Edit Layout."] = "전투 중 파티를 위한 한 줄: 오른쪽 끝에 1위 플레이어와 그 값, 나머지는 1위 대비 비율 위치의 직업 아이콘, 나는 더 큰 아이콘이고 줄은 내 직업 색으로 나까지 채워집니다. 전투가 시작되면 나타나고 끝나면 사라집니다. 포인터를 올리면 모두의 목록. 레이아웃 편집에서 옮기세요.", -- draft
	["Race Bar Shows"] = "경주 막대 표시", -- draft
	["What the race bar races. Auto: healing while your group role is healer, else damage."] = "경주 막대가 겨루는 것. 자동: 파티 역할이 치유 전담이면 치유, 아니면 피해.", -- draft
	["Auto"] = "자동", -- draft
	["Damage"] = "피해", -- draft
	["Healing"] = "치유", -- draft
	["Race Bar Pins"] = "경주 막대 핀", -- draft
	["The most players on the race bar: the best ones, and always you."] = "경주 막대에 오르는 최대 플레이어 수: 상위 플레이어, 그리고 항상 나.", -- draft
	["Race Bar Width"] = "경주 막대 폭", -- draft
	["How wide the race bar is. Also in Edit Layout: right-click the race bar."] = "경주 막대의 폭. 레이아웃 편집에서도: 경주 막대를 오른쪽 클릭.", -- draft
	["Race Bar Thickness"] = "경주 막대 두께", -- draft
	["How thick your share is on the race bar's line (its pins and labels keep their size). Also in Edit Layout: right-click the race bar."] = "경주 막대 줄에서 내 몫의 두께(핀과 이름표는 크기 유지). 레이아웃 편집에서도: 경주 막대를 오른쪽 클릭.", -- draft
	["Fight Summary"] = "전투 요약", -- draft
	["After a fight, for a few seconds in the widget column (longer while you point at it): won or lost and its length, your damage, DPS and rank, the ring your share of the group. The pointer on it shows the top five; a click opens the fight in the Fight History."] = "전투 후 위젯 열에 몇 초간(가리키고 있으면 더 오래): 승패와 시간, 내 피해, DPS, 순위, 고리는 파티 내 내 몫. 포인터를 올리면 상위 5명, 누르면 전투 기록에서 그 전투가 열립니다.", -- draft
	["Fight History"] = "전투 기록", -- draft
	["The Fight History window: every fight of this session, grouped by run, with the damage, healing and your spells of each. It opens from its button in the chat's button column and from the summary. It takes the place of the game's meter windows."] = "전투 기록 창: 이번 세션의 모든 전투를 던전별로 묶어 각각의 피해, 치유, 내 주문을 보여 줍니다. 대화 버튼 열의 버튼과 요약에서 엽니다. 게임의 측정기 창을 대신합니다.", -- draft
	["Fights Kept"] = "보관할 전투 수", -- draft
	["How many fights the history keeps, the oldest dropped first. Kept over a /reload; a new login starts it empty."] = "기록이 보관하는 전투 수, 가장 오래된 것부터 삭제. /reload 후에도 유지되며 새로 접속하면 비어서 시작합니다.", -- draft
	-- SwingTimers
	["Swing Timers"] = "자동 공격 타이머", -- draft
	["A shot bar and a melee bar in MelloUI's look in place of the game's swing timers: each swing and shot counted down beside your weapon's icon, the off hand under the main hand, a wand's shots on the melee bar. The game's own swing timers are switched off while this is on, and come back as you had them when it is off. While the Personal Display shows your swing on its rails (Swing On The Rails), these bars step aside."] = "게임의 자동 공격 타이머 대신 MelloUI 외형의 사격 막대와 근접 막대: 모든 공격과 사격을 무기 아이콘 옆에서 카운트다운, 보조 장비는 주 장비 아래, 마법봉 사격은 근접 막대에. 켜져 있는 동안 게임의 자동 공격 타이머는 꺼지고, 끄면 원래대로 돌아옵니다. 개인 표시기가 레일에 공격을 보여 주는 동안(레일 위 공격)에는 이 막대들이 비켜납니다.", -- draft
	["Every swing and shot at a glance."] = "모든 공격과 사격을 한눈에.", -- draft
	["Shot Bar"] = "사격 막대", -- draft
	["The shot bar for a bow, gun, crossbow or thrown weapon while Auto Shot is on: cream, shrinking to the middle while it reloads (you can move), then red, growing from the middle while you aim: stand still, moving holds the shot back."] = "자동 사격이 켜져 있을 때 활, 총, 석궁, 투척 무기의 사격 막대: 장전 중에는 크림색으로 가운데로 줄어들고(움직여도 됨), 조준 중에는 빨갛게 가운데서 늘어납니다: 가만히 서 있으세요, 움직이면 사격이 미뤄집니다.", -- draft
	["Melee Bar"] = "근접 막대", -- draft
	["The melee bar: each swing of your main hand counted down, shrinking to the middle. A wand's shots (Shoot) count down on it too."] = "근접 막대: 주 장비의 각 공격을 가운데로 줄어들며 카운트다운. 마법봉 사격(사격)도 여기서 카운트다운합니다.", -- draft
	["Off Hand Bar"] = "보조 장비 막대", -- draft
	["A thinner bar under the melee bar for your off-hand weapon's swings, while you carry one."] = "보조 장비 무기를 들고 있을 때 그 공격을 위한 근접 막대 아래의 더 얇은 막대.", -- draft
	["Seconds"] = "초", -- draft
	["The seconds left, past the bar's right end; on the shot bar Hold and Moving there while you aim. Off: the bars alone."] = "막대 오른쪽 끝 너머의 남은 초. 조준 중 사격 막대에는 그 자리에 정지와 이동 중. 끄기: 막대만.", -- draft
	["Width"] = "폭", -- draft
	["How wide the bars are; the weapon's rim hangs left of them and the seconds right of them. Also in Edit Layout (right-click a bar there)."] = "막대의 폭. 무기 테는 왼쪽에, 초는 오른쪽에 붙습니다. 레이아웃 편집에서도(거기서 막대를 오른쪽 클릭).", -- draft
	["Height"] = "높이", -- draft
	["How tall the bars are; the off hand's is 60 % of it, and the weapon's rim grows with them from 15 on. Also in Edit Layout."] = "막대의 높이. 보조 장비 막대는 그 60 %이며, 무기 테는 15부터 함께 커집니다. 레이아웃 편집에서도.", -- draft
	["In Combat: a bar shows in a fight once it swings or shoots, and fades out when the fight ends (the shot bar also when Auto Shot stops). Always: each bar shows while you carry a weapon for it, at rest between swings."] = "전투 중: 막대가 전투 중 공격하거나 쏘면 나타나고 전투가 끝나면 사라집니다(사격 막대는 자동 사격이 멈출 때도). 항상: 해당 무기를 들고 있는 동안 각 막대가 보이며, 공격 사이에는 멈춰 있습니다.", -- draft
	["In Combat"] = "전투 중", -- draft
	["Always"] = "항상", -- draft
	-- PartyMarkers
	["Party Markers"] = "파티 표시", -- draft
	["A class medallion above every party member's friendly nameplate, with a ring in their role's colour. In the open world; inside instances the game keeps friendly nameplates to itself."] = "모든 파티원의 아군 이름표 위에 역할 색 고리를 두른 직업 메달. 야외에서만. 인스턴스 안에서는 게임이 아군 이름표를 독점합니다.", -- draft
	["A class medallion over every party member's head, ringed in their role's colour: the healer, found at a glance."] = "모든 파티원 머리 위의 역할 색 고리를 두른 직업 메달: 치유사를 한눈에.", -- draft
	["Markers"] = "표시", -- draft
	["Mark"] = "표시 대상", -- draft
	["Whose nameplate gets the class medallion above the name."] = "이름 위에 직업 메달을 받는 이름표.", -- draft
	["Party and raid members"] = "파티원과 공격대원", -- draft
	["Every friendly player"] = "모든 아군 플레이어", -- draft
	["Marker Size"] = "표시 크기", -- draft
	["The medallion's size above the name."] = "이름 위 메달의 크기.", -- draft
	["Height Above The Name"] = "이름 위 높이", -- draft
	["The gap between the name and the medallion."] = "이름과 메달 사이의 간격.", -- draft
	["Role Ring"] = "역할 고리", -- draft
	["A coloured ring around the medallion for the member's assigned role: green healer, blue tank, red damage. Only when the group has roles set (the group finder sets them; a party can set them by hand)."] = "파티원에게 지정된 역할 색의 메달 둘레 고리: 녹색 치유, 파랑 방어, 빨강 피해. 파티에 역할이 정해져 있을 때만(파티 찾기가 정해 주며, 파티는 직접 정할 수 있음).", -- draft
	["Open world only: inside instances the game keeps friendly nameplates to itself"] = "야외에서만: 인스턴스 안에서는 게임이 아군 이름표를 독점합니다", -- draft
	-- Sparkles
	["Loot Sparkles"] = "전리품 반짝임", -- draft
	["The game's sparkle on quest items you can loot, kept on through its graphics presets, and golden glints over the ore veins and herbs you walk up to: dim out of reach, bright in reach, grey when your skill is too low. The game settings it needs come back as you had them when it is off."] = "주울 수 있는 퀘스트 아이템에 대한 게임의 반짝임을 그래픽 사전 설정과 상관없이 유지하고, 다가가는 광맥과 약초에 금빛 반짝임: 닿지 않으면 흐리게, 닿으면 밝게, 기술이 부족하면 회색. 끄면 필요한 게임 설정이 원래대로 돌아옵니다.", -- draft
	["What you can loot, at a glance."] = "주울 수 있는 것을 한눈에.", -- draft
	["Quest Item Sparkles"] = "퀘스트 아이템 반짝임", -- draft
	["Keeps the game's sparkle on quest items you can loot. It needs the game's outline mode off, which its graphics presets switch back on: held while this is on, given back as you had it when off. Switching this off takes the sparkles away after the next game restart (the client's own; /reload is not enough)."] = "주울 수 있는 퀘스트 아이템에 대한 게임의 반짝임을 유지합니다. 게임의 윤곽선 모드가 꺼져 있어야 하는데, 그래픽 사전 설정이 이를 다시 켭니다: 켜져 있는 동안 유지하고, 끄면 원래대로 돌려 놓습니다. 끄면 다음 게임 재시작 후 반짝임이 사라집니다(클라이언트 재시작; /reload로는 부족).", -- draft
	["Ore Veins"] = "광맥", -- draft
	["Golden glints over the ore vein you walk up to (the game's soft targeting picks the nearest one, within about 15 yards): dim out of reach, bright once you can mine it, grey when your skill is too low."] = "다가가는 광맥 위의 금빛 반짝임(게임의 소프트 대상 지정이 약 15미터 안의 가장 가까운 것을 고름): 닿지 않으면 흐리게, 캘 수 있으면 밝게, 기술이 부족하면 회색.", -- draft
	["Herbs"] = "약초", -- draft
	["The same glints over the herb you walk up to."] = "다가가는 약초 위의 같은 반짝임.", -- draft
	["Quest Objects"] = "퀘스트 물체", -- draft
	["The same glints over a quest object you walk up to. Off by default: the game's own sparkle (Quest Item Sparkles) already marks most of them."] = "다가가는 퀘스트 물체 위의 같은 반짝임. 기본 꺼짐: 게임의 반짝임(퀘스트 아이템 반짝임)이 이미 대부분을 표시합니다.", -- draft
	-- CustomSounds
	["Custom Sounds"] = "사용자 지정 소리", -- draft
	["The interface's sounds replaced by the custom library: iron, leather, parchment and stone for clicks, windows, bags, gear, vendors, whispers and the group finder."] = "인터페이스 소리를 사용자 지정 라이브러리로 바꿉니다: 클릭, 창, 가방, 장비, 상인, 귓속말, 파티 찾기에 철, 가죽, 양피지, 돌 소리.", -- draft
	["Iron, leather, parchment and stone. Every click, page, pouch and buckle of the interface, re-recorded."] = "철, 가죽, 양피지, 돌. 인터페이스의 모든 클릭, 페이지, 주머니, 버클을 새로 녹음했습니다.", -- draft
	["Sounds"] = "소리", -- draft
	["Clicks"] = "클릭", -- draft
	["Buttons, checkboxes, tabs and scroll arrows: light clicks, a heavy one for Okay/Accept, a latch releasing for Cancel, Quit and abandoning a quest."] = "버튼, 확인란, 탭, 스크롤 화살표: 가벼운 클릭, 확인/수락에는 무거운 클릭, 취소, 게임 종료, 퀘스트 포기에는 걸쇠가 풀리는 소리.", -- draft
	["Windows"] = "창", -- draft
	["A page turn when the character sheet, spell book, quest log or main menu opens, a latch when they close; the spell book's page turns; a quest giver's list and Decline; the bags as a leather pouch opening and closing."] = "캐릭터 정보, 마법책, 퀘스트 목록, 주 메뉴가 열릴 때 페이지 넘김, 닫힐 때 걸쇠 소리. 마법책 페이지 넘김, 퀘스트 제공자 목록과 거절, 가죽 주머니처럼 열리고 닫히는 가방.", -- draft
	["Inventory"] = "소지품", -- draft
	["An item picked up, moved between slots, put down or looted; a rare or better item has its own sound. Silences the game's own pick-up and put-down sounds (the Equipment and Vendor sounds rely on that, and play only while this is on)."] = "아이템을 집거나, 칸 사이로 옮기거나, 내려놓거나, 주울 때. 희귀 이상 아이템은 자체 소리. 게임의 집기와 내려놓기 소리를 끕니다(장비와 상인 소리가 여기에 의존하며 이것이 켜져 있을 때만 납니다).", -- draft
	["Equipment"] = "장비", -- draft
	["Buckles and plate for armour, a steel slide for weapons, jewellery ticks for rings, necks and trinkets; straps loosening when something is taken off."] = "방어구에는 버클과 판금, 무기에는 강철 미끄러지는 소리, 반지, 목걸이, 장신구에는 장신구 딸깍. 무언가를 벗을 때 끈 풀리는 소리.", -- draft
	["Coins on the counter when buying, coins into the pouch when selling (the automatic grey sale too)."] = "살 때는 계산대 위의 동전, 팔 때는 주머니에 들어가는 동전(자동 회색 판매도).", -- draft
	["Social"] = "소셜", -- draft
	["A note under the door for a whisper, two knocks for a group invite."] = "귓속말에는 문 아래로 들어오는 쪽지, 파티 초대에는 노크 두 번.", -- draft
	["Group Finder"] = "파티 찾기", -- draft
	["The ledger for entering a queue or applying to a listing, a strike-through for leaving it, the bell for a group that is ready and for a ready check."] = "대기열에 들어가거나 등록에 신청할 때는 장부, 나갈 때는 줄 긋기, 준비된 파티와 준비 확인에는 종소리.", -- draft
	["The workbench when an item is crafted."] = "아이템을 제작하면 작업대 소리.", -- draft
	["Quests"] = "퀘스트", -- draft
	["The mechanism engaging when a quest is turned in."] = "퀘스트를 완료하면 장치가 맞물리는 소리.", -- draft
	["Errors"] = "오류", -- draft
	["A muted knock for the game's red error messages (\"You can't do that yet\"), at most one every half second; none for a message Error Messages hides."] = "게임의 빨간 오류 메시지(\"아직 사용할 수 없습니다.\")에 둔탁한 노크, 0.5초에 최대 한 번. 오류 메시지가 숨기는 메시지에는 없음.", -- draft
	["Targets"] = "대상", -- draft
	["An iron sight catching when a target is selected, a latch releasing when it is lost."] = "대상을 고르면 철 조준기가 걸리는 소리, 잃으면 걸쇠가 풀리는 소리.", -- draft
	["A seal struck into the record when you level."] = "레벨이 오르면 기록에 찍히는 인장.", -- draft
	["Loot Coins"] = "전리품 동전", -- draft
	["Coins into the pouch when money is looted."] = "돈을 주우면 주머니에 들어가는 동전.", -- draft
	["Spell Icons"] = "주문 아이콘", -- draft
	["A page lifting when a spell, macro or ability is dragged, the slot latching when it is placed."] = "주문, 매크로, 기술을 끌면 페이지가 들리고, 놓으면 칸이 걸립니다.", -- draft
	["Map Ping"] = "지도 신호", -- draft
	["An iron pin into the parchment for a minimap ping."] = "미니맵 신호에는 양피지에 꽂히는 철 핀.", -- draft
	["Scroll Wheel"] = "스크롤 휠", -- draft
	["One cog notch per mouse-wheel step on any list, window or the chat. The game has no wheel sound; this is an addition."] = "목록, 창, 대화에서 마우스 휠 한 칸마다 톱니 소리 하나. 게임에는 휠 소리가 없으며, 이것은 추가 기능입니다.", -- draft
	["Hover Ticks"] = "가리키기 딸깍", -- draft
	["A tiny tick when the mouse reaches a button. The game has no hover sound; this is an addition."] = "마우스가 버튼에 닿으면 작은 딸깍. 게임에는 가리키기 소리가 없으며, 이것은 추가 기능입니다.", -- draft
	["Output"] = "출력", -- draft
	["Sound Channel"] = "소리 채널", -- draft
	["The game volume slider the sounds follow."] = "소리가 따르는 게임 음량 슬라이더.", -- draft
	["Sound Effects"] = "효과음", -- draft
	["Master"] = "주 음량", -- draft
