	["Power Bar Height"] = "자원 막대 높이", -- draft
	["How tall the power bar is."] = "자원 막대의 높이.", -- draft
	["Power Colour"] = "자원 색", -- draft
	["The power bar's colour: the power's own (blue mana, red rage, yellow energy), the member's class colour, or one of yours."] = "자원 막대의 색: 자원 자체의 색(파란 마나, 빨간 분노, 노란 기력), 구성원의 직업 색, 또는 내 색 중 하나.", -- draft
