	["Name Colour"] = "이름 색", -- draft
	["The name's colour: white, the member's class colour, or one of yours."] = "이름의 색: 흰색, 구성원의 직업 색, 또는 내 색 중 하나.", -- draft
	["White"] = "흰색", -- draft
	["My Name Colour"] = "내 이름 색", -- draft
